INSERT INTO announcements (id, title, content, category, action_url, action_label, pinned, created_at, images, pdf_url, pdf_name)
VALUES 
  ('11111111-1111-1111-1111-111111111111', '📢 ประกาศแจ้งกำหนดการชำระค่าลงทะเบียนและอุปกรณ์ฝึกซ้อม JRE 2027', 'ขอให้ผู้สมัครที่ได้รับการยืนยันสิทธิ์ ดำเนินการชำระค่าธรรมเนียมบำรุงอุปกรณ์การฝึก จำนวน 350 บาท (รวมเสื้อกั๊กสะท้อนแสง ป้ายชื่อ และอาหาร 5 มื้อ) ภายในวันที่ 31 ตุลาคม 2569 เวลา 23:59 น. ผ่านบัญชีโครงการ ชมรมกู้ภัยราชพฤกษ์ ธนาคารกรุงไทย เลขที่ 984-0-XXXXX-X พร้อมส่งสลิปในกลุ่มไลน์', 'payment', 'https://line.me', 'ส่งหลักฐานการโอนเงิน', true, '2026-10-01T10:00:00Z', '[]'::jsonb, '', ''),
  ('22222222-2222-2222-2222-222222222222', '💬 ประกาศลิงก์เข้าร่วม Line OpenChat ประจำรุ่น JRE 2027', 'สำหรับผู้สมัครทุกคน โปรดเข้าร่วมกลุ่ม Line OpenChat "JRE 2027 เครือข่ายกู้ภัยนักศึกษาทั่วประเทศ (ทุกภูมิภาค)" เพื่อรับการแจ้งเตือนด่วน สรุปเอกสารการฝึก และประสานงานเรื่องการเดินทางและที่พัก', 'line_group', 'https://line.me', 'กดเพื่อเข้าร่วมกลุ่ม Line', true, '2026-10-01T11:00:00Z', '[]'::jsonb, '', ''),
  ('33333333-3333-3333-3333-333333333333', '📋 ประกาศคำสั่งโครงการและรายการอุปกรณ์ประจำกายที่ต้องจัดเตรียม', 'ผู้เข้าร่วมอบรมต้องจัดเตรียม: 1. กางเกงขายาวผ้าหนาสำหรับฝึก 2. รองเท้าหุ้มส้นหรือรองเท้าเซฟตี้ 3. ถุงมือผ้าหรือถุงมือหนัง 4. ไฟฉายส่องสว่างส่วนบุคคล 5. ยาประจำตัวและของใช้ส่วนตัวสำหรับพักค้างแรม 1 คืน', 'order', '', '', false, '2026-10-02T09:00:00Z', '[]'::jsonb, '', ''),
  ('44444444-4444-4444-4444-444444444444', '⚡ ประกาศการเปลี่ยนแปลงจุดรวมพลพิธีเปิด (Update)', 'แจ้งเปลี่ยนแปลงจุดรวมพลพิธีเปิดในวันที่ 7 พ.ย. 2569 จากเดิมโถงชั้น 1 ปรับเป็นห้องประชุมใหญ่ ชั้น 2 อาคารบรมราชกุมารี เพื่อความสะดวกรวดเร็วในการลงทะเบียนและรับฟังการบรรยาย', 'change', '', '', false, '2026-10-02T15:30:00Z', '[]'::jsonb, '', '')
